52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private final ClinicService clinicService;
58	
59	    private final OwnerMapper ownerMapper;
60	
61	    private final PetMapper petMapper;
62	
63	    private final VisitMapper visitMapper;
64	
65	    public OwnerRestControllerV1(ClinicService clinicService,
66	                                 OwnerMapper ownerMapper,
67	                                 PetMapper petMapper,
68	                                 VisitMapper visitMapper) {
69	        this.clinicService = clinicService;
70	        this.ownerMapper = ownerMapper;
71	        this.petMapper = petMapper;
72	        this.visitMapper = visitMapper;
73	    }
74	
75	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
76	    @Override
77	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
78	        Collection<Owner> owners;
79	        if (lastName != null) {
80	            owners = this.clinicService.findOwnerByLastName(lastName);
81	        } else {
82	            owners = this.clinicService.findAllOwners();
83	        }
84	        if (owners.isEmpty()) {
85	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
86	        }
87	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
93	        Owner owner = this.clinicService.findOwnerById(ownerId);
94	        if (owner == null) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
98	        if (Households.memberCount(this.clinicService.findAllOwners(), owner) >= 3) {
99	            ownerDto.setMembershipLevel(4);
100	        }
101	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        HttpHeaders headers = new HttpHeaders();
108	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
109	        Collection<Owner> owners = this.clinicService.findAllOwners();
110	        if (DailyRegistrations.countOn(owners, java.time.LocalDate.now()) >= 100) {
111	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
112	        }
113	        if (CityCodes.count(owners, owner) >= 50) {
114	            return new ResponseEntity<>(HttpStatus.CONFLICT);
115	        }
116	        owner.setHouseholdId(Households.householdId(owners,
117	            Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()), owner));
118	        if (IdentityKeys.isDuplicate(owners, owner)) {
119	            return new ResponseEntity<>(HttpStatus.CONFLICT);
120	        }
121	        owner.setBulkSignupWarning(DailyRegistrations.countOn(owners, java.time.LocalDate.now()) > 80);
122	        owner.setNamesakeCount(Namesakes.count(owners, owner));
123	        owner.assignCustomerCode(CityCodes.count(owners, owner) + 1);
124	        this.clinicService.saveOwner(owner);
125	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
126	        headers.setLocation(UriComponentsBuilder.newInstance()
127	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
128	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
134	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
135	        if (currentOwner == null) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        currentOwner.setAddress(ownerFieldsDto.getAddress());
139	        currentOwner.setCity(ownerFieldsDto.getCity());
140	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
141	        currentOwner.setLastName(ownerFieldsDto.getLastName());
142	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
143	        this.clinicService.saveOwner(currentOwner);
144	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Transactional
149	    @Override
150	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
151	        Owner owner = this.clinicService.findOwnerById(ownerId);
152	        if (owner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        this.clinicService.deleteOwner(owner);
156	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
162	        Owner owner = this.clinicService.findOwnerById(ownerId);
163	        if (owner == null) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        HttpHeaders headers = new HttpHeaders();
167	        Pet pet = petMapper.toPet(petFieldsDto);
168	        owner.setId(ownerId);
169	        pet.setOwner(owner);
170	        pet.getType().setName(null);
171	        this.clinicService.savePet(pet);
172	        PetDto petDto = petMapper.toPetDto(pet);
173	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
174	            .buildAndExpand(pet.getId()).toUri());
175	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
181	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
182	        if (currentOwner != null) {
183	            Pet currentPet = this.clinicService.findPetById(petId);
184	            if (currentPet != null) {
185	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
186	                currentPet.setName(petFieldsDto.getName());
187	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
188	                this.clinicService.savePet(currentPet);
189	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
190	            }
191	        }
192	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
193	    }
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Override
197	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
198	        HttpHeaders headers = new HttpHeaders();
199	        Visit visit = visitMapper.toVisit(visitFieldsDto);
200	        Pet pet = new Pet();
201	        pet.setId(petId);
202	        visit.setPet(pet);
203	        this.clinicService.saveVisit(visit);
204	        VisitDto visitDto = visitMapper.toVisitDto(visit);
205	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
206	            .buildAndExpand(visit.getId()).toUri());
207	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
208	    }
209	
210	
211	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
212	    @Override
213	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
214	        Owner owner = this.clinicService.findOwnerById(ownerId);
215	        if (owner != null) {
216	            Pet pet = owner.getPet(petId);
217	            if (pet != null) {
218	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
219	            }
220	        }
221	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
222	    }
223	}
