29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	@EntityListeners(OwnerAuditListener.class)
40	public class Owner extends Person {
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "city")
46	    @NotEmpty
47	    private String city;
48	
49	    @Column(name = "telephone")
50	    @NotEmpty
51	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 format")
52	    private String telephone;
53	
54	    @Column(name = "email")
55	    private String email;
56	
57	    @Column(name = "postcode")
58	    private String postcode;
59	
60	    public String getPostcode() {
61	        return this.postcode;
62	    }
63	
64	    public void setPostcode(String postcode) {
65	        this.postcode = postcode;
66	    }
67	
68	    @Column(name = "registration_date")
69	    private LocalDate registrationDate;
70	
71	    @Column(name = "customer_code")
72	    private String customerCode;
73	
74	    public String getCustomerCode() {
75	        return this.customerCode;
76	    }
77	
78	    public void setCustomerCode(String customerCode) {
79	        this.customerCode = customerCode;
80	    }
81	
82	    /** Assign the customer code '<CITY3>-<LAST3>-<NNNN>' for the given per-city sequence number. */
83	    public void assignCustomerCode(int sequence) {
84	        this.customerCode = getCity().substring(0, 3).toUpperCase() + "-"
85	            + getLastName().substring(0, 3).toUpperCase() + String.format("-%04d", sequence);
86	    }
87	
88	    @Transient
89	    private String householdId;
90	
91	    public String getHouseholdId() {
92	        return this.householdId;
93	    }
94	
95	    public void setHouseholdId(String householdId) {
96	        this.householdId = householdId;
97	    }
98	
99	    @Transient
100	    private Integer namesakeCount;
101	
102	    public Integer getNamesakeCount() {
103	        return this.namesakeCount;
104	    }
105	
106	    public void setNamesakeCount(Integer namesakeCount) {
107	        this.namesakeCount = namesakeCount;
108	    }
109	
110	    @Transient
111	    private Boolean bulkSignupWarning;
112	
113	    public Boolean getBulkSignupWarning() {
114	        return this.bulkSignupWarning;
115	    }
116	
117	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
118	        this.bulkSignupWarning = bulkSignupWarning;
119	    }
120	
121	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
122	    private Set<Pet> pets;
123	
124	    public String getEmail() {
125	        return this.email;
126	    }
127	
128	    /** Store the email lower-cased so it is persisted and returned normalised. */
129	    public void setEmail(String email) {
130	        this.email = (email == null) ? null : email.toLowerCase();
131	    }
132	
133	    public LocalDate getRegistrationDate() {
134	        return this.registrationDate;
135	    }
136	
137	    public void setRegistrationDate(LocalDate registrationDate) {
138	        this.registrationDate = registrationDate;
139	    }
140	
141	    /** Default a missing registration date to the server's current date, then roll the
142	     *  effective date forward to a business day (a weekend becomes the next Monday). */
143	    @PrePersist
144	    protected void ensureRegistrationDate() {
145	        LocalDate effective = (this.registrationDate == null) ? LocalDate.now() : this.registrationDate;
146	        this.registrationDate = BusinessDays.rollForward(effective);
147	    }
148	
149	    public String getAddress() {
150	        return this.address;
151	    }
152	
153	    public void setAddress(String address) {
154	        this.address = address;
155	    }
156	
157	    public String getCity() {
158	        return this.city;
159	    }
160	
161	    public void setCity(String city) {
162	        this.city = city;
163	    }
164	
165	    public String getTelephone() {
166	        return this.telephone;
167	    }
168	
169	    public void setTelephone(String telephone) {
170	        this.telephone = telephone;
171	    }
172	
173	    protected Set<Pet> getPetsInternal() {
174	        if (this.pets == null) {
175	            this.pets = new HashSet<>();
176	        }
177	        return this.pets;
178	    }
179	
180	    protected void setPetsInternal(Set<Pet> pets) {
181	        this.pets = pets;
182	    }
183	
184	    public List<Pet> getPets() {
185	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
186	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
187	        return Collections.unmodifiableList(sortedPets);
188	    }
189	
190	    public void setPets(List<Pet> pets) {
191	        this.pets = new HashSet<>(pets);
192	    }
193	
194	    public void addPet(Pet pet) {
195	        getPetsInternal().add(pet);
196	        pet.setOwner(this);
197	    }
198	
199	    /**
200	     * Return the Pet with the given name, or null if none found for this Owner.
201	     *
202	     * @param name to test
203	     * @return true if pet name is already in use
204	     */
205	    public Pet getPet(String name) {
206	        return getPet(name, false);
207	    }
208	
209	    /**
210	     * Return the Pet with the given name, or null if none found for this Owner.
211	     *
212	     * @param name to test
213	     * @return true if pet name is already in use
214	     */
215	    public Pet getPet(String name, boolean ignoreNew) {
216	        name = name.toLowerCase();
217	        for (Pet pet : getPetsInternal()) {
218	            if (!ignoreNew || !pet.isNew()) {
219	                String compName = pet.getName();
220	                compName = compName.toLowerCase();
221	                if (compName.equals(name)) {
222	                    return pet;
223	                }
224	            }
225	        }
226	        return null;
227	    }
228	
229	    public Pet getPet(Integer petId) {
230	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
231	    }
232	
233	    @Override
234	    public String toString() {
235	        return new ToStringCreator(this)
236	
237	            .append("id", this.getId())
238	            .append("new", this.isNew())
239	            .append("lastName", this.getLastName())
240	            .append("firstName", this.getFirstName())
241	            .append("address", this.address)
242	            .append("city", this.city)
243	            .append("telephone", this.telephone)
244	            .toString();
245	    }
246	}
