9	/**
10	 * Detects owners that share a household, i.e. carry the same last name and the
11	 * same address compared case-insensitively with collapsed whitespace.
12	 */
13	final class Households {
14	
15	    private Households() {
16	    }
17	
18	    /** Trim, collapse internal whitespace and lower-case a value for comparison. */
19	    private static String normalize(String value) {
20	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
21	    }
22	
23	    /** How many of the given owners belong to the candidate's household (share its last name
24	     *  and address, compared case-insensitively with collapsed whitespace). */
25	    static long memberCount(Collection<Owner> owners, Owner candidate) {
26	        String lastName = normalize(candidate.getLastName());
27	        String address = normalize(candidate.getAddress());
28	        return owners.stream().filter(o ->
29	            normalize(o.getLastName()).equals(lastName) && normalize(o.getAddress()).equals(address)).count();
30	    }
31	
32	    /** True when an existing owner has the candidate's last name and address. */
33	    static boolean isDuplicate(Collection<Owner> existing, Owner candidate) {
34	        String lastName = normalize(candidate.getLastName());
35	        String address = normalize(candidate.getAddress());
36	        return existing.stream().anyMatch(o ->
37	            normalize(o.getLastName()).equals(lastName) && normalize(o.getAddress()).equals(address));
38	    }
39	
40	    /**
41	     * The stable household id to assign to an owner, or {@code null} when it is not
42	     * joining one. Derived from the normalized last name and address, so every owner
43	     * that joins the same household is given the same identifier.
44	     */
45	    static String householdId(Collection<Owner> existing, boolean sharesHousehold, Owner candidate) {
46	        if (!sharesHousehold || !isDuplicate(existing, candidate)) {
47	            return null;
48	        }
49	        String key = normalize(candidate.getLastName()) + "\n" + normalize(candidate.getAddress());
50	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
51	    }
52	}
