21	     *  (E.164); a missing email or household id contributes an empty segment. */
22	    public static String of(Owner owner) {
23	        String email = owner.getEmail() == null ? "" : owner.getEmail();
24	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
25	        return owner.getTelephone() + "|" + email + "|" + householdId;
26	    }
