17	package org.springframework.samples.petclinic.util;
18	
19	/**
20	 * Normalises a telephone number to E.164 form ({@code '+'} country code and national digits).
21	 *
22	 * <p>A leading {@code '+'} is treated as an explicit country code and kept verbatim; otherwise the
23	 * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped from
24	 * the national digits. Spaces, dashes and brackets are stripped. The result must carry 8 to 15
25	 * digits after the {@code '+'}, else the input cannot form a valid E.164 number.
26	 */
27	public abstract class E164 {
28	
29	    /**
30	     * @param raw the raw telephone input, may be {@code null}
31	     * @return the E.164 string, or {@code null} when {@code raw} is {@code null}
32	     * @throws IllegalArgumentException when {@code raw} cannot form a valid E.164 number
33	     */
34	    public static String toE164(String raw) {
35	        if (raw == null) {
36	            return null;
37	        }
38	        boolean explicitCountryCode = raw.trim().startsWith("+");
39	        String digits = raw.replaceAll("\\D", "");
40	        String national = explicitCountryCode ? digits
41	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
42	        if (national.length() < 8 || national.length() > 15 || !nationalLengthValid(national)) {
43	            throw new IllegalArgumentException("Telephone cannot form a valid E.164 number: " + raw);
44	        }
45	        return "+" + national;
46	    }
47	
48	    /**
49	     * Checks the national-number length against a country code that fixes it: {@code '+61'} requires
50	     * 9 national digits and {@code '+1'} requires 10. Other country codes are unconstrained here.
51	     *
52	     * @param national the country code followed by the national digits
53	     * @return {@code true} unless {@code national}'s country code mandates a different length
54	     */
55	    private static boolean nationalLengthValid(String national) {
56	        if (national.startsWith("61")) {
57	            return national.length() - 2 == 9;
58	        }
59	        if (national.startsWith("1")) {
60	            return national.length() - 1 == 10;
61	        }
62	        return true;
63	    }
64	
65	}
