3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	/**
7	 * Business-day helper: a weekend date rolls forward to the following Monday;
8	 * weekday dates are returned unchanged.
9	 */
10	public final class BusinessDays {
11	
12	    private BusinessDays() {
13	    }
14	
15	    /** Roll a Saturday/Sunday forward to the next Monday; a weekday is returned unchanged. */
16	    public static LocalDate rollForward(LocalDate date) {
17	        DayOfWeek day = date.getDayOfWeek();
18	        if (day == DayOfWeek.SATURDAY) {
19	            return date.plusDays(2);
20	        }
21	        if (day == DayOfWeek.SUNDAY) {
22	            return date.plusDays(1);
23	        }
24	        return date;
25	    }
26	}
